1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Computes an owner's {@code identityKey}: a derived, human-readable summary of the fields
7	 * that identify an owner. The key is
8	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
9	 *
10	 * <p>Household membership itself is enforced separately by {@link RequireUniqueIdentity},
11	 * which rejects a second owner in the same household (same {@code householdId}, derived from
12	 * lastName + postcode) unless it declares {@code sharesHousehold}.
13	 *
14	 * <ul>
15	 * <li>telephone is normalized to E.164 form ({@link Telephones#toE164(String)}),
16	 * <li>email is trimmed and lower-cased, contributing empty when absent,
17	 * <li>householdId is the owner's deterministic household identifier (from lastName +
18	 *     postcode), empty only when it has not been assigned.
19	 * </ul>
20	 */
21	public final class IdentityKeys {
22	
23	    private IdentityKeys() {
24	    }
25	
26	    /** The identity key of an existing owner, from its stored fields. */
27	    public static String forOwner(Owner owner) {
28	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
29	    }
30	
31	    /**
32	     * The identity key for an incoming create request, from its raw fields and its derived
33	     * {@code householdId}. Lets {@link RequireUniqueIdentity} compare a request against
34	     * existing owners' {@link #forOwner(Owner) keys} without first building an entity.
35	     */
36	    public static String forFields(String telephone, String email, String householdId) {
37	        return build(telephone, email, householdId);
38	    }
39	
40	    private static String build(String telephone, String email, String householdId) {
41	        String tel = Telephones.toE164(telephone);
42	        return (tel == null ? "" : tel) + "|" + normalizeEmail(email) + "|"
43	                + (householdId == null ? "" : householdId);
44	    }
45	
46	    /** Trim and lower-case; null or blank yields empty (no email to contribute). */
47	    private static String normalizeEmail(String email) {
48	        if (email == null || email.isBlank()) {
49	            return "";
50	        }
51	        return email.trim().toLowerCase();
52	    }
53	}
54

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Derives the stable {@code householdId} shared by owners with the same last name and
7	 * postcode. The id is the {@link #hash(String) SHA-256 prefix} of the normalized last name
8	 * and the postcode, so every owner in the same household (same normalized last name +
9	 * postcode) maps to the same value automatically — no opt-in is required.
10	 *
11	 * <p>Centralising the derivation here keeps {@link AssignHousehold} (which assigns the id)
12	 * and {@link IdentityKeys} (which folds it into an owner's identity key) in exact agreement.
13	 */
14	public final class Households {
15	
16	    private Households() {
17	    }
18	
19	    /** The stable {@code householdId} for the given last name and postcode. */
20	    public static String idFor(String lastName, String postcode) {
21	        return hash(normalize(lastName) + "|" + (postcode == null ? "" : postcode));
22	    }
23	
24	    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
25	    public static String normalize(String value) {
26	        if (value == null) {
27	            return "";
28	        }
29	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
30	    }
31	
32	    /** Stable 12-hex-character (upper-case) prefix of the SHA-256 of the household key. */
33	    private static String hash(String value) {
34	        return Digests.sha256Hex(value).substring(0, 12).toUpperCase(Locale.ROOT);
35	    }
36	}
37

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The one place that turns a string into its SHA-256 hex digest. Several owner
9	 * derivations are built on the same hash — {@link Households} (the {@code householdId}
10	 * prefix) and {@link CustomerCodes} (the {@code HASH8} segment) both fold their key
11	 * through it — so keeping the encoding here means every one of them agrees on the exact
12	 * bytes and hex form instead of each hand-rolling {@link MessageDigest}.
13	 *
14	 * <p>{@link #sha256Hex(String)} is the primitive: the full, lower-case hex string. Callers
15	 * that want a shorter, upper-case identifier take a {@code substring} and upper-case it, so
16	 * the slicing and casing stay a decision of the derivation, not of the hash.
17	 */
18	public final class Digests {
19	
20	    private Digests() {
21	    }
22	
23	    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
24	    public static String sha256Hex(String value) {
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest(value.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(digest.length * 2);
29	            for (byte b : digest) {
30	                sb.append(String.format("%02x", b));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException e) {
35	            throw new IllegalStateException("SHA-256 not available", e);
36	        }
37	    }
38	}
