1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create request that exactly duplicates an existing owner's identity. Identity is
11	 * the {@link IdentityKeys#forFields(String, String, String) identity key} —
12	 * {@code telephone + email + householdId}, where {@code householdId} is derived from
13	 * (lastName, postcode) via {@link Households} — so a second owner in the same household is a
14	 * legitimate, distinct household member (different telephone) rather than a duplicate; only a
15	 * true resubmit (same telephone, email and household) collides and is reported as a 409 by
16	 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityExceptionHandler}.
17	 *
18	 * <p>Setting {@code sharesHousehold} bypasses this block entirely: the owner is then created
19	 * as a declared household member (and, being declared, is not flagged as a possible duplicate
20	 * by {@link AssignPossibleDuplicate}). Owners in different households always derive a
21	 * different {@code householdId}, so they never collide here.
22	 */
23	public class RequireUniqueIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // a declared household member bypasses the duplicate block
29	        }
30	        String householdId = Households.idFor(request.getLastName(), request.getPostcode());
31	        String identityKey = IdentityKeys.forFields(request.getTelephone(), request.getEmail(),
32	                householdId);
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
35	                continue; // a soft-deleted owner does not block a new create
36	            }
37	            if (identityKey.equals(IdentityKeys.forOwner(existing))) {
38	                throw new DuplicateIdentityException(householdId);
39	            }
40	        }
41	    }
42	}
