1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's deterministic {@code householdId}, derived from the normalized last
8	 * name and postcode by {@link Households}. Because the id is a pure function of
9	 * (lastName, postcode), every owner with the same last name and postcode maps to the same
10	 * value automatically — there is no opt-in and no back-fill of existing rows. {@code
11	 * sharesHousehold} no longer creates the link; it only bypasses the duplicate block in
12	 * {@link RequireUniqueIdentity}. {@link IdentityKeys} folds the same value into an owner's
13	 * identity key, so the stored {@code householdId} always matches its household component.
14	 */
15	public class AssignHousehold {
16	
17	    public void service(@Val Owner owner) {
18	        owner.setHouseholdId(Households.idFor(owner.getLastName(), owner.getPostcode()));
19	    }
20	}
