1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's {@code possibleDuplicate} / {@code possibleDuplicateOf}: a soft-match
10	 * flag for a new owner that is not a hard duplicate but still looks like one.
11	 *
12	 * <p>A create is only rejected (409) when the new owner joins an existing household without
13	 * declaring it (see {@link RequireUniqueIdentity}), so by the time this step runs the new
14	 * owner is either in a fresh household or a declared member. Here we flag the weaker signal:
15	 * an existing owner that shares the same {@code lastName} (compared case-insensitively) and
16	 * the same {@code postcode}. A <em>declared</em> household member ({@code sharesHousehold})
17	 * is intentionally never flagged — a declared member is not a suspected duplicate. Otherwise,
18	 * when a match is found the owner is still created, but with {@code possibleDuplicate} true
19	 * and {@code possibleDuplicateOf} set to the (lowest) matching owner id; when none is found
20	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
21	 *
22	 * <p>Runs after {@link BuildOwner} (so the owner's fields are set) and before
23	 * {@link SaveOwner} (so the new owner is not compared against itself).
24	 */
25	public class AssignPossibleDuplicate {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
28	            OwnerRepository ownerRepository) {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            // A declared household member is not a suspected duplicate.
31	            owner.setPossibleDuplicate(false);
32	            owner.setPossibleDuplicateOf(null);
33	            return;
34	        }
35	        String lastName = owner.getLastName();
36	        String postcode = owner.getPostcode();
37	        Integer matchId = null;
38	        if (lastName != null && postcode != null && !postcode.isBlank()) {
39	            for (Owner existing : ownerRepository.findAll()) {
40	                if (Boolean.TRUE.equals(existing.getDeleted())) {
41	                    continue; // a soft-deleted owner is not a possible duplicate
42	                }
43	                if (lastName.equalsIgnoreCase(existing.getLastName())
44	                        && postcode.equals(existing.getPostcode())
45	                        && (matchId == null || existing.getId() < matchId)) {
46	                    matchId = existing.getId();
47	                }
48	            }
49	        }
50	        owner.setPossibleDuplicate(matchId != null);
51	        owner.setPossibleDuplicateOf(matchId);
52	    }
53	}
