1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.RequiredFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Rejects a create request that is missing or blank in any required owner field,
15	 * before {@link BuildOwner} runs. The names of the offending fields are reported
16	 * as a 400 by {@link org.springframework.samples.petclinic.rest.escalation.RequiredFieldsExceptionHandler}.
17	 *
18	 * <p>This is a manual guard rather than {@code @Valid} so that a missing or blank
19	 * required field yields the {@code errors} field-name array this endpoint promises,
20	 * instead of the generic schema-validation problem detail.
21	 */
22	public class RequireOwnerFields {
23	
24	    /** A pragmatic syntactic email check: a local part, an '@', and a dotted domain,
25	     *  none containing whitespace or a second '@'. */
26	    private static final Pattern EMAIL_PATTERN =
27	            Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
28	
29	    /** Disposable email domains that are never accepted, matched case-insensitively. */
30	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
31	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
32	
33	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
34	            throws RequiredFieldsException {
35	        List<String> errors = new ArrayList<>();
36	        checkField("firstName", request.getFirstName(), errors);
37	        checkField("lastName", request.getLastName(), errors);
38	        // Address: the structured fields are preferred when present; the flat 'address'
39	        // input stays accepted for backward compatibility. An owner is valid when it
40	        // supplies an address in EITHER form — a non-blank 'addressLine1' or the flat
41	        // 'address'. Normalization applies to whichever fields are supplied, before the
42	        // required check, so a blank-after-normalization address is rejected and the
43	        // stored/returned values are canonical.
44	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
45	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
46	        String flat = AddressNormalizer.normalize(request.getAddress());
47	        boolean structured = !line1.isEmpty();
48	        String effectiveLine1 = structured ? line1 : flat;
49	        if (effectiveLine1.isEmpty()) {
50	            errors.add("address");
51	        }
52	        else {
53	            // The composed 'address' is the normalized addressLine1, with a single space
54	            // and the normalized addressLine2 appended when addressLine2 is present.
55	            String composed = (structured && !line2.isEmpty())
56	                    ? effectiveLine1 + " " + line2 : effectiveLine1;
57	            request.setAddress(composed);
58	            request.setAddressLine1(structured ? line1 : null);
59	            request.setAddressLine2(structured && !line2.isEmpty() ? line2 : null);
60	        }
61	        checkField("city", request.getCity(), errors);
62	        checkField("telephone", request.getTelephone(), errors);
63	        if (!errors.isEmpty()) {
64	            throw new RequiredFieldsException(errors);
65	        }
66	        // Normalize the telephone to E.164 form; reject when it cannot form a valid one.
67	        String telephone = Telephones.toE164(request.getTelephone());
68	        if (telephone == null) {
69	            throw new RequiredFieldsException(List.of("telephone"));
70	        }
71	        request.setTelephone(telephone);
72	        // Email is optional; when present it must be syntactically valid and is
73	        // stored and returned lower-cased.
74	        String email = request.getEmail();
75	        if (email != null && !email.isBlank()) {
76	            if (!EMAIL_PATTERN.matcher(email).matches()) {
77	                throw new RequiredFieldsException(List.of("email"));
78	            }
79	            String lowerEmail = email.toLowerCase();
80	            // Reject disposable-domain addresses: the domain (text after the last '@')
81	            // must not be on the blocklist.
82	            String domain = lowerEmail.substring(lowerEmail.lastIndexOf('@') + 1);
83	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
84	                throw new RequiredFieldsException(List.of("email"));
85	            }
86	            request.setEmail(lowerEmail);
87	        }
88	        // Postcode is optional; when present it must be a 4-digit code that is valid for
89	        // the owner's city per the fixed region ranges (a city with no known region accepts
90	        // any 4-digit code). Validated here only when supplied, so a request without a
91	        // postcode stays accepted.
92	        if (!Postcodes.isValid(request.getPostcode(), request.getCity())) {
93	            throw new RequiredFieldsException(List.of("postcode"));
94	        }
95	        validated.set(request);
96	    }
97	
98	    private static void checkField(String name, String value, List<String> errors) {
99	        if (value == null || value.isBlank()) {
100	            errors.add(name);
101	        }
102	    }
103	}
