3	/**
4	 * Thrown when a create request would join an existing household (same {@code householdId},
5	 * derived from lastName + postcode) without declaring {@code sharesHousehold}. Handled by
6	 * {@link DuplicateIdentityExceptionHandler}, which responds 409 Conflict.
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    public DuplicateIdentityException(String householdId) {
11	        super("An owner in household '" + householdId + "' already exists");
12	    }
13	}
