1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.mapper.Localities;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's {@code customerCode}, the {@code <REGION>-<HASH8>} identity every
10	 * other owner-code-derived value is built from.
11	 *
12	 * <p>{@code REGION} is the region code derived from the owner's postcode
13	 * ({@link Localities#forPostcode(String)}), or {@code UNKNOWN} when the postcode is
14	 * absent or in no known range. {@code HASH8} is the first 8 upper-case hex characters
15	 * of the SHA-256 digest of the normalized telephone ({@link Telephones#toE164(String)})
16	 * concatenated with the last name. There are no sequence numbers: the identity is a
17	 * pure function of the owner's own fields.
18	 *
19	 * <p>Centralising the derivation here keeps {@link AssignCustomerCode} (which assigns
20	 * the code) and the {@code locality} mapping (which reads the region back off it) in
21	 * exact agreement.
22	 */
23	public final class CustomerCodes {
24	
25	    private CustomerCodes() {
26	    }
27	
28	    /** The {@code <REGION>-<HASH8>} customerCode for the given owner. */
29	    public static String forOwner(Owner owner) {
30	        return region(owner.getPostcode()) + "-" + hash8(owner);
31	    }
32	
33	    /**
34	     * The owner's locality: the {@code REGION} segment of its customerCode, so the
35	     * locality is derived from the region-and-hash identity. Falls back to the
36	     * postcode-derived region for owners without a customerCode.
37	     */
38	    public static String localityOf(Owner owner) {
39	        String code = owner.getCustomerCode();
40	        if (code != null) {
41	            int dash = code.indexOf('-');
42	            if (dash > 0) {
43	                return code.substring(0, dash);
44	            }
45	        }
46	        return region(owner.getPostcode());
47	    }
48	
49	    /**
50	     * The owner's IANA timezone, derived from its {@link #localityOf(Owner) locality}
51	     * via the fixed region-to-timezone table, or {@code null} when the region is unknown.
52	     */
53	    public static String timezoneOf(Owner owner) {
54	        return Localities.timezoneForRegion(localityOf(owner));
55	    }
56	
57	    /** The region code derived from a postcode, or {@code UNKNOWN} when unresolved. */
58	    public static String region(String postcode) {
59	        String region = Localities.forPostcode(postcode);
60	        return region != null ? region : "UNKNOWN";
61	    }
62	
63	    /** First 8 upper-case hex chars of SHA-256 over (normalizedTelephone + lastName). */
64	    private static String hash8(Owner owner) {
65	        String telephone = Telephones.toE164(owner.getTelephone());
66	        String lastName = owner.getLastName();
67	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
68	        return Digests.sha256Hex(basis).substring(0, 8).toUpperCase(Locale.ROOT);
69	    }
70	}
71

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdSize}: the number of owners sharing this owner's
9	 * {@code householdId} after this create, i.e. every existing member already carrying the
10	 * same id (back-filled by {@link AssignHousehold}) plus this owner. Runs after
11	 * {@link AssignHousehold} but before the owner is saved, so the new owner is counted with
12	 * a {@code +1}. Owners not in a shared household (null {@code householdId}) count as one.
13	 */
14	public class AssignHouseholdSize {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        if (householdId == null) {
19	            owner.setHouseholdSize(1);
20	            return;
21	        }
22	        int count = 1; // this owner, not yet saved
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                count++;
26	            }
27	        }
28	        owner.setHouseholdSize(count);
29	    }
30	}
